SELECT CASE WHEN pressure >= 1016 THEN 'LARGE' ELSE 'SMALL' END AS pressure_tier, device_code, AVG(humidity) FILTER (WHERE device_code = 'DV-03') AS dv_03_avg_humidity, CORR(pressure, humidity) AS corr_pressure_humidity, COUNT(DISTINCT firmware) AS distinct_firmwares, COUNT(DISTINCT device_code) AS distinct_device_codes, SIZE(COLLECT_SET(device_code)) AS num_device_codes, ROUND(AVG(temp_c), 2) AS avg_temp_c FROM device_readings GROUP BY CASE WHEN pressure >= 1016 THEN 'LARGE' ELSE 'SMALL' END, device_code
